package main

import (
	"image"
	"image/color"
	"image/jpeg"
	"os"
	"fmt"
)

func gradW(w,h int) *image.Gray {
	img:=image.NewGray(image.Rect(0,0,w,h))
	for y:=0;y<h;y++{
		for x:=0;x<w;x++{
			v := uint8(float64(x)/float64(w-1)*255)
			img.SetGray(x,y,color.Gray{Y:v})
		}
	}
	return img
}
func solid(w,h, v int) *image.Gray{
	img:=image.NewGray(image.Rect(0,0,w,h))
	for y:=0;y<h;y++{
		for x:=0;x<w;x++{
			img.SetGray(x,y,color.Gray{Y:uint8(v)})
		}
	}
	return img
}

func checker(w,h int) *image.Gray{
	img:=image.NewGray(image.Rect(0,0,w,h))
	for y:=0;y<h;y++{
		for x:=0;x<w;x++{
			var v uint8
			if x%2==0 { v=0 } else { v=255 }
			img.SetGray(x,y,color.Gray{Y:v})
		}
	}
	return img
}

func main(){
	// produce raw yuv? Let's try to inspect jpeg library behavior?
	// For testing sample positions, we need to understand how jp2a samples.
	// Let's try to create jpeg where pixel values alternate black/white columns to deduce sampling offsets.
	// For i in understanding, let's brute test: if src 10 width, out 5 width, what source x does it sample?
	// Based on jp2a code, original C: it computes something like: for res_x from 0 to width-1, src_x = (res_x * src_width) / width ?
	// Or maybe with floating?
	// But we saw later gx100x1 width10 gave all zeros, which suggests maybe when height=1 sampling Y goes out?
	// Let's try height 2 vs 1.
	fname:=os.Args[len(os.Args)-1]
	width,height:=10,2
	fmt.Sscanf(os.Args[2],"%d",&width)
	fmt.Sscanf(os.Args[3],"%d",&height)
	mode:=os.Args[1]
	var img *image.Gray
	switch mode{
	case "gx":
		img=gradW(width,height)
	case "solid":
		val:=0
		fmt.Sscanf(os.Args[4],"%d",&val)
		img=solid(width,height,val)
	case "checker":
		img=checker(width,height)
	case "stripe":
		// stripe of width? first N black rest white?
		// args: width height split output
		split:=width/2
		if len(os.Args)>=5{
			fmt.Sscanf(os.Args[4],"%d",&split)
		}
		img=image.NewGray(image.Rect(0,0,width,height))
		for y:=0;y<height;y++{
			for x:=0;x<width;x++{
				var v uint8=255
				if x<split { v=0 }
				img.SetGray(x,y,color.Gray{Y:v})
			}
		}
	}
	f,_:=os.Create(fname)
	defer f.Close()
	jpeg.Encode(f, img, &jpeg.Options{Quality:100})
}
