# So for vertical 5, k=2 gives positions [0,20,40,59,79] => blocks [0,2,5,7,9] matches. That's using formula (i*(79)+k)//4.
# For vertical 6, k=4 gives [0,16,32,48,64,79] blocks [0,2,4,6,8,9] matches.
# For horizontal 5, no k matches? We found earlier that horizontal 5 mismatch with block exact? Let's brute search for more general formulas that include src instead of src-1, and also central offset.

def brute2(src,out,expected):
    best=[]
    # general: src_pos = (i*src + a)//out + b? Let's try 2d search.
    for a in range(-out, out*2):
        for b in range(-8,8):
            pos=[(i*src + a)//out + b for i in range(out)]
            # clamp
            pos=[max(0,min(src-1,p)) for p in pos]
            blocks=[p//8 for p in pos]
            if blocks==expected:
                best.append((a,b,pos))
                if len(best)>5:
                    return best
    return best

print("vertical 5", brute2(80,5,[0,2,5,7,9])[:2])
print("vertical 6", brute2(80,6,[0,2,4,6,8,9])[:2])
print("horizontal 5", brute2(80,5,[1,3,4,6,8])[:2])
print("horizontal 6", brute2(80,6,[0,2,4,5,7,9])[:2])
print("horizontal 7", brute2(80,7,[0,2,3,4,6,7,9])[:2])
print("horizontal 8", brute2(80,8,[0,1,3,4,5,6,8,9])[:2])

