package main

import (
	"image/jpeg"
	"os"
	"fmt"
)

func main(){
	f,_:=os.Open(os.Args[1])
	defer f.Close()
	img,_:=jpeg.Decode(f)
	b:=img.Bounds()
	// print first row gray values
	// if it's not gray, convert
	for y:=0;y<b.Dy() && y<1; y++{
		for x:=0;x<b.Dx(); x++{
			r,g,b,_:=img.At(x,y).RGBA()
			// r is 16-bit
			fmt.Printf("%d ", r>>8)
			if x%8==7 { fmt.Print("| ") }
		}
		fmt.Println()
