func getTerminalSize() (int,int,error){
	// Try env vars
	colsStr:=os.Getenv("COLUMNS")
	linesStr:=os.Getenv("LINES")
	term:=os.Getenv("TERM")
	if term==""{
		return 0,0,fmt.Errorf("TERM not set")
	}
	if colsStr=="" || linesStr==""{
		// try stty? but no
		return 0,0,fmt.Errorf("no size")
	}
	c, err1:=strconv.Atoi(colsStr)
	l, err2:=strconv.Atoi(linesStr)
	if err1!=nil || err2!=nil{
		return 0,0,fmt.Errorf("bad size")
	}
	// usable lines = lines-1 as deduced
	return c, l-1, nil
}

func sampleImage(img image.Image, outW, outH int, flipx, flipy bool) ([][]color.RGBA){
	// We'll sample using floor? Let's use center for now to match H more often.
	bounds:=img.Bounds()
	srcW:=bounds.Dx()
	srcH:=bounds.Dy()
	result := make([][]color.RGBA, outH)
	for y:=0;y<outH;y++{
		// srcY = floor((float64(y)+0.5)*float64(srcH)/float64(outH))
		srcY := int((float64(y)+0.5)*float64(srcH)/float64(outH))
		if srcY<0{srcY=0}
		if srcY>=srcH{srcY=srcH-1}
		if flipy{
			srcY = srcH-1 - srcY
		}
		row := make([]color.RGBA, outW)
		for x:=0;x<outW;x++{
			srcX := int((float64(x)+0.5)*float64(srcW)/float64(outW))
			if srcX<0{srcX=0}
			if srcX>=srcW{srcX=srcW-1}
			if flipx{
				srcX = srcW-1 - srcX
			}
			c := img.At(bounds.Min.X+srcX, bounds.Min.Y+srcY)
			// convert to RGBA
			r,g,b,a := c.RGBA()
			row[x]=color.RGBA{uint8(r>>8), uint8(g>>8), uint8(b>>8), uint8(a>>8)}
		}
		result[y]=row
	}
	return result
}

