			if srcX<0{srcX=0}
			if srcX>=srcW{srcX=srcW-1}
			if flipx{
				srcX = srcW-1 - srcX
			}
			c := img.At(bounds.Min.X+srcX, bounds.Min.Y+srcY)
			// convert to RGBA
			r,g,b,a := c.RGBA()
			row[x]=color.RGBA{uint8(r>>8), uint8(g>>8), uint8(b>>8), uint8(a>>8)}
		}
		result[y]=row
	}
	return result
}

