func getTerminalSize() (int, int, error) {
	colsStr := os.Getenv("COLUMNS")
	linesStr := os.Getenv("LINES")
	term := os.Getenv("TERM")
	if term == "" {
		return 0, 0, fmt.Errorf("TERM not set")
	}
	if colsStr == "" || linesStr == "" {
		return 0, 0, fmt.Errorf("no size")
	}
	c, err1 := strconv.Atoi(colsStr)
	l, err2 := strconv.Atoi(linesStr)
	if err1 != nil || err2 != nil {
		return 0, 0, fmt.Errorf("bad size")
	}
	return c, l - 1, nil
}

