func htmlEscape(s string) string {
	r := strings.NewReplacer("&", "&amp;", "<", "&lt;", ">", "&gt;", "\"", "&quot;", "'", "&#39;")
	return r.Replace(s)
}

func htmlCharEscape(ch rune) string {
	switch ch {
	case '&':
		return "&amp;"
	case '<':
		return "&lt;"
	case '>':
		return "&gt;"
	case '"':
		return "&quot;"
	case ' ':
		return "&nbsp;"
	default:
		if ch < 32 || ch > 126 {
			return fmt.Sprintf("&#%d;", ch)
		}
		return string(ch)
	}
}
