)

var defaultChars = "   ...',;:clodxkO0KXNWM"

type Config struct {
	width, height int
	widthSet, heightSet bool
	chars string
	border, clear, colors, debug, fill, flipx, flipy bool
	termFit, termHeight, termWidth, termZoom bool
	grayscale bool
