				}
			}
			switch a {
			case "-b":
				cfg.border = true
			case "-d":
				cfg.debug = true
			case "-x":
				cfg.flipx = true
			case "-y":
				cfg.flipy = true
			case "-f":
				cfg.termFit = true
			case "-z":
				cfg.termZoom = true
			case "-i":
				cfg.invert = !cfg.invert
