			continue
		}
		if strings.HasPrefix(a, "--") {
			opt := a
			val := ""
			hasEq := false
			if eq := strings.Index(a, "="); eq != -1 {
				opt = a[:eq]
				val = a[eq+1:]
				hasEq = true
			}
			switch opt {
			case "--blue":
				if !hasEq {
					fatalUnknown(a)
				}
				f, err := strconv.ParseFloat(val, 64)
				if err != nil {
					fatalUnknown(a)
				}
				cfg.blue = f
				cfg.blueSet = true
			case "--border":
				cfg.border = true
			case "--chars":
				if !hasEq {
					fatalUnknown(a)
				}
				cfg.chars = val
			case "--clear":
				cfg.clear = true
			case "--colors":
				cfg.colors = true
			case "--debug":
				cfg.debug = true
			case "--fill":
				cfg.fill = true
			case "--flipx":
				cfg.flipx = true
			case "--flipy":
				cfg.flipy = true
			case "--term-fit":
				cfg.termFit = true
			case "--term-height":
				cfg.termHeight = true
			case "--term-width":
				cfg.termWidth = true
			case "--term-zoom":
				cfg.termZoom = true
			case "--grayscale":
				cfg.grayscale = true
			case "--green":
				if !hasEq {
					fatalUnknown(a)
				}
				f, err := strconv.ParseFloat(val, 64)
				if err != nil {
					fatalUnknown(a)
				}
				cfg.green = f
				cfg.greenSet = true
			case "--height":
