}

func main() {
	cfg := Config{
		chars: defaultChars,
		red:   0.2989,
		green: 0.5866,
		blue:  0.1145,
		htmlFontSize: 4,
		htmlTitle:    "jp2a converted image",
		output:       "-",
	}
	args := os.Args[1:]
	files := []string{}
	for i := 0; i < len(args); {
		a := args[i]
		if a == "-" {
			files = append(files, "-")
			i++
			continue
		}
		if a == "--" {
			files = append(files, args[i+1:]...)
			break
		}
		if strings.HasPrefix(a, "-") && !strings.HasPrefix(a, "--") {
			if len(a) > 2 {
				handled := true
				for _, ch := range a[1:] {
					switch ch {
					case 'b':
						cfg.border = true
					case 'd':
						cfg.debug = true
					case 'x':
						cfg.flipx = true
					case 'y':
						cfg.flipy = true
					case 'f':
						cfg.termFit = true
					case 'z':
						cfg.termZoom = true
					case 'i':
						cfg.invert = !cfg.invert
					case 'h':
						cfg.help = true
					case 'v':
						cfg.verbose = true
					case 'V':
						cfg.version = true
					default:
						handled = false
					}
				}
				if handled {
					i++
					continue
				}
			}
			switch a {
			case "-b":
				cfg.border = true
			case "-d":
				cfg.debug = true
			case "-x":
				cfg.flipx = true
			case "-y":
				cfg.flipy = true
			case "-f":
				cfg.termFit = true
			case "-z":
				cfg.termZoom = true
			case "-i":
				cfg.invert = !cfg.invert
			case "-h":
				cfg.help = true
			case "-v":
				cfg.verbose = true
			case "-V":
				cfg.version = true
			default:
				fatalUnknown(a)
			}
			i++
			continue
		}
		if strings.HasPrefix(a, "--") {
			opt := a
			val := ""
			hasEq := false
			if eq := strings.Index(a, "="); eq != -1 {
				opt = a[:eq]
				val = a[eq+1:]
				hasEq = true
			}
			switch opt {
			case "--blue":
				if !hasEq {
					fatalUnknown(a)
				}
				f, err := strconv.ParseFloat(val, 64)
				if err != nil {
					fatalUnknown(a)
				}
				cfg.blue = f
				cfg.blueSet = true
			case "--border":
				cfg.border = true
			case "--chars":
				if !hasEq {
					fatalUnknown(a)
				}
				cfg.chars = val
			case "--clear":
				cfg.clear = true
			case "--colors":
				cfg.colors = true
			case "--debug":
				cfg.debug = true
			case "--fill":
				cfg.fill = true
			case "--flipx":
				cfg.flipx = true
			case "--flipy":
				cfg.flipy = true
			case "--term-fit":
				cfg.termFit = true
			case "--term-height":
				cfg.termHeight = true
			case "--term-width":
				cfg.termWidth = true
			case "--term-zoom":
				cfg.termZoom = true
			case "--grayscale":
				cfg.grayscale = true
			case "--green":
				if !hasEq {
					fatalUnknown(a)
				}
				f, err := strconv.ParseFloat(val, 64)
				if err != nil {
					fatalUnknown(a)
				}
				cfg.green = f
				cfg.greenSet = true
			case "--height":
				if !hasEq {
					fatalUnknown(a)
				}
				h, err := strconv.Atoi(val)
				if err != nil {
					fatalUnknown(a)
				}
				cfg.height = h
				cfg.heightSet = true
			case "--help":
				cfg.help = true
			case "--html":
				cfg.html = true
			case "--html-fill":
				cfg.fill = true
			case "--html-fontsize":
				if !hasEq {
					fatalUnknown(a)
				}
				sz, err := strconv.Atoi(val)
				if err != nil {
					fatalUnknown(a)
				}
				cfg.htmlFontSize = sz
			case "--html-no-bold":
				cfg.htmlNoBold = true
			case "--html-raw":
				cfg.htmlRaw = true
			case "--html-title":
				if !hasEq {
					fatalUnknown(a)
				}
				cfg.htmlTitle = val
			case "--invert":
				cfg.invert = !cfg.invert
			case "--background":
				if !hasEq {
					fatalUnknown(a)
				}
				if val == "dark" {
					cfg.invert = false
				} else if val == "light" {
					cfg.invert = true
				} else {
