				}
			case "--output":
				if !hasEq {
					fatalUnknown(a)
				}
				cfg.output = val
			case "--red":
				if !hasEq {
					fatalUnknown(a)
				}
				f, err := strconv.ParseFloat(val, 64)
				if err != nil {
					fatalUnknown(a)
				}
				cfg.red = f
				cfg.redSet = true
			case "--size":
				if !hasEq {
					fatalUnknown(a)
				}
				parts := strings.Split(val, "x")
				if len(parts) != 2 {
					fatalUnknown(a)
				}
				w, err1 := strconv.Atoi(parts[0])
				h, err2 := strconv.Atoi(parts[1])
				if err1 != nil || err2 != nil {
					fatalUnknown(a)
				}
				cfg.width = w
				cfg.height = h
				cfg.widthSet = true
				cfg.heightSet = true
			case "--verbose":
				cfg.verbose = true
			case "--version":
				cfg.version = true
