      --term-width  Use terminal display width.
  -z, --term-zoom   Use terminal display dimension for output.
      --grayscale   Convert image to grayscale when using --html or --colors
      --green=N.N   Set RGB to grayscale conversion weight, default is 0.5866
      --height=N    Set output height, calculate width from aspect ratio.
  -h, --help        Print program help.
      --html        Produce strict XHTML 1.0 output.
      --html-fill   Same as --fill (will be phased out)
      --html-fontsize=N   Set fontsize to N pt, default is 4.
      --html-no-bold      Do not use bold characters with HTML output
      --html-raw    Output raw HTML codes, i.e. without the <head> section etc.
      --html-title=...  Set HTML output title
  -i, --invert      Invert output image.  Use if your display has a dark
                    background.
      --background=dark   These are just mnemonics whether to use --invert
      --background=light  or not.  If your console has light characters on
                    a dark background, use --background=dark.
      --output=...  Write output to file.
      --red=N.N     Set RGB to grayscale conversion weight, default 0.2989f.
      --size=WxH    Set output width and height.
  -v, --verbose     Verbose output.
  -V, --version     Print program version.
      --width=N     Set output width, calculate height from ratio.

  The default mode is ` + "`jp2a --term-fit --background=dark'." + `
  See the man-page for jp2a for more detailed help text.

Project homepage on https://github.com/cslarsen/jp2a
Report bugs to <csl@csl.name>`)
}

func printVersion() {
	fmt.Println(`jp2a 1.0.8
Copyright 2006-2016 Christian Stigen Larsen
Distributed under the GNU General Public License (GPL) v2.`)
}

func fatalUnknown(a string) {
	fmt.Fprintf(os.Stderr, "Unknown option %s\n\n", a)
	printHelp()
	os.Exit(1)
}

func main() {
	cfg := Config{
		chars: defaultChars,
		red:   0.2989,
		green: 0.5866,
		blue:  0.1145,
		htmlFontSize: 4,
		htmlTitle:    "jp2a converted image",
		output:       "-",
	}
	args := os.Args[1:]
	files := []string{}
	for i := 0; i < len(args); {
		a := args[i]
		if a == "-" {
			files = append(files, "-")
			i++
			continue
		}
		if a == "--" {
			files = append(files, args[i+1:]...)
			break
		}
		if strings.HasPrefix(a, "-") && !strings.HasPrefix(a, "--") {
			if len(a) > 2 {
				handled := true
				for _, ch := range a[1:] {
					switch ch {
					case 'b':
						cfg.border = true
					case 'd':
						cfg.debug = true
					case 'x':
						cfg.flipx = true
					case 'y':
						cfg.flipy = true
					case 'f':
						cfg.termFit = true
					case 'z':
						cfg.termZoom = true
					case 'i':
						cfg.invert = !cfg.invert
					case 'h':
						cfg.help = true
					case 'v':
						cfg.verbose = true
					case 'V':
						cfg.version = true
					default:
						handled = false
					}
				}
				if handled {
					i++
					continue
				}
			}
			switch a {
			case "-b":
				cfg.border = true
			case "-d":
				cfg.debug = true
			case "-x":
				cfg.flipx = true
			case "-y":
				cfg.flipy = true
			case "-f":
				cfg.termFit = true
			case "-z":
				cfg.termZoom = true
			case "-i":
				cfg.invert = !cfg.invert
			case "-h":
				cfg.help = true
			case "-v":
				cfg.verbose = true
			case "-V":
				cfg.version = true
			default:
				fatalUnknown(a)
			}
			i++
			continue
		}
		if strings.HasPrefix(a, "--") {
			opt := a
			val := ""
			hasEq := false
			if eq := strings.Index(a, "="); eq != -1 {
				opt = a[:eq]
				val = a[eq+1:]
				hasEq = true
			}
			switch opt {
			case "--blue":
				if !hasEq {
					fatalUnknown(a)
				}
				f, err := strconv.ParseFloat(val, 64)
				if err != nil {
					fatalUnknown(a)
				}
				cfg.blue = f
				cfg.blueSet = true
			case "--border":
				cfg.border = true
			case "--chars":
				if !hasEq {
					fatalUnknown(a)
				}
				cfg.chars = val
			case "--clear":
				cfg.clear = true
			case "--colors":
				cfg.colors = true
			case "--debug":
				cfg.debug = true
			case "--fill":
				cfg.fill = true
			case "--flipx":
				cfg.flipx = true
			case "--flipy":
				cfg.flipy = true
			case "--term-fit":
				cfg.termFit = true
			case "--term-height":
				cfg.termHeight = true
			case "--term-width":
				cfg.termWidth = true
			case "--term-zoom":
				cfg.termZoom = true
			case "--grayscale":
				cfg.grayscale = true
			case "--green":
				if !hasEq {
					fatalUnknown(a)
				}
				f, err := strconv.ParseFloat(val, 64)
				if err != nil {
					fatalUnknown(a)
				}
				cfg.green = f
				cfg.greenSet = true
			case "--height":
				if !hasEq {
					fatalUnknown(a)
				}
				h, err := strconv.Atoi(val)
				if err != nil {
					fatalUnknown(a)
				}
				cfg.height = h
				cfg.heightSet = true
			case "--help":
				cfg.help = true
			case "--html":
				cfg.html = true
			case "--html-fill":
				cfg.fill = true
			case "--html-fontsize":
				if !hasEq {
					fatalUnknown(a)
				}
				sz, err := strconv.Atoi(val)
				if err != nil {
					fatalUnknown(a)
				}
				cfg.htmlFontSize = sz
			case "--html-no-bold":
				cfg.htmlNoBold = true
			case "--html-raw":
				cfg.htmlRaw = true
			case "--html-title":
				if !hasEq {
					fatalUnknown(a)
				}
				cfg.htmlTitle = val
			case "--invert":
				cfg.invert = !cfg.invert
			case "--background":
				if !hasEq {
					fatalUnknown(a)
				}
				if val == "dark" {
					cfg.invert = false
				} else if val == "light" {
					cfg.invert = true
				} else {
					fatalUnknown(a)
				}
			case "--output":
				if !hasEq {
					fatalUnknown(a)
				}
				cfg.output = val
			case "--red":
				if !hasEq {
					fatalUnknown(a)
				}
				f, err := strconv.ParseFloat(val, 64)
				if err != nil {
					fatalUnknown(a)
				}
				cfg.red = f
				cfg.redSet = true
			case "--size":
				if !hasEq {
					fatalUnknown(a)
				}
				parts := strings.Split(val, "x")
				if len(parts) != 2 {
					fatalUnknown(a)
				}
				w, err1 := strconv.Atoi(parts[0])
				h, err2 := strconv.Atoi(parts[1])
				if err1 != nil || err2 != nil {
					fatalUnknown(a)
				}
				cfg.width = w
				cfg.height = h
				cfg.widthSet = true
				cfg.heightSet = true
			case "--verbose":
				cfg.verbose = true
			case "--version":
				cfg.version = true
			case "--width":
				if !hasEq {
					fatalUnknown(a)
				}
				w, err := strconv.Atoi(val)
				if err != nil {
					fatalUnknown(a)
				}
				cfg.width = w
				cfg.widthSet = true
			case "--zoom":
				cfg.termZoom = true
			default:
				fatalUnknown(a)
			}
			i++
			continue
		}
		files = append(files, a)
		i++
	}

	if cfg.help {
		printHelp()
		os.Exit(0)
	}
	if cfg.version {
		printVersion()
		os.Exit(0)
	}
	if len([]rune(cfg.chars)) < 2 {
		fmt.Fprintln(os.Stderr, "At least two characters must be specified.")
		printHelp()
		os.Exit(1)
	}
	if cfg.redSet || cfg.greenSet || cfg.blueSet {
		sum := cfg.red + cfg.green + cfg.blue
		if math.Abs(sum-1.0) > 0.0001 {
			fmt.Fprintln(os.Stderr, "Weights RED + GREEN + BLUE must equal 1.0")
			os.Exit(1)
		}
	}

	termW, termH, termErr := getTerminalSize()

	if len(files) == 0 {
		fmt.Fprintln(os.Stderr, "No files specified.")
		printHelp()
		os.Exit(1)
	}

	var outWriter io.Writer = os.Stdout
	var outFile *os.File
	if cfg.output != "-" && cfg.output != "" {
		f, err := os.Create(cfg.output)
		if err != nil {
			fmt.Fprintf(os.Stderr, "Could not open '%s' for writing.\n", cfg.output)
			os.Exit(1)
		}
		outFile = f
		defer f.Close()
		outWriter = f
	}

	if !cfg.widthSet && !cfg.heightSet && !cfg.termFit && !cfg.termWidth && !cfg.termHeight && !cfg.termZoom {
		cfg.termFit = true
	}

	for idx, fname := range files {
		var img image.Image
		var srcW, srcH int

		if strings.HasPrefix(fname, "http://") || strings.HasPrefix(fname, "https://") {
			if cfg.debug {
				fmt.Fprintf(os.Stderr, "*   Trying %s\n", fname)
			}
			resp, err := http.Get(fname)
			if err != nil {
				fmt.Fprintln(os.Stderr, "Empty input file")
				os.Exit(1)
			}
			data, _ := io.ReadAll(resp.Body)
			resp.Body.Close()
			if len(data) == 0 {
				fmt.Fprintln(os.Stderr, "Empty input file")
				os.Exit(1)
			}
			r := bytes.NewReader(data)
			decoded, err := jpeg.Decode(r)
			if err != nil {
				fmt.Fprintln(os.Stderr, "Empty input file")
				os.Exit(1)
			}
			img = decoded
			srcW = img.Bounds().Dx()
			srcH = img.Bounds().Dy()
		} else if fname == "-" {
			data, err := io.ReadAll(os.Stdin)
			if err != nil || len(data) == 0 {
				fmt.Fprintln(os.Stderr, "Empty input file")
				os.Exit(1)
			}
			r := bytes.NewReader(data)
			decoded, err := jpeg.Decode(r)
			if err != nil {
				fmt.Fprintln(os.Stderr, "Empty input file")
				os.Exit(1)
			}
			img = decoded
			srcW = img.Bounds().Dx()
			srcH = img.Bounds().Dy()
		} else {
			f, err := os.Open(fname)
			if err != nil {
				fmt.Fprintln(os.Stderr, "Empty input file")
				os.Exit(1)
			}
			decoded, err := jpeg.Decode(f)
			f.Close()
			if err != nil {
				fmt.Fprintln(os.Stderr, "Empty input file")
				os.Exit(1)
			}
			img = decoded
			srcW = img.Bounds().Dx()
			srcH = img.Bounds().Dy()
		}

		outW, outH := 0, 0
		if cfg.widthSet && cfg.heightSet {
			outW = cfg.width
			outH = cfg.height
		} else if cfg.widthSet {
			outW = cfg.width
			outH = int(math.Round(float64(outW) * float64(srcH) / float64(srcW) * 0.5))
			if outH < 1 {
				outH = 1
			}
		} else if cfg.heightSet {
			outH = cfg.height
			outW = int(math.Round(float64(outH) * float64(srcW) / float64(srcH) * 2.0))
			if outW < 1 {
				outW = 1
			}
		} else if cfg.termWidth {
			if termErr != nil {
				fmt.Fprintln(os.Stderr, "Environment variable TERM not set.")
				os.Exit(1)
			}
			outW = termW
			outH = int(math.Round(float64(outW) * float64(srcH) / float64(srcW) * 0.5))
			if outH < 1 {
				outH = 1
			}
		} else if cfg.termHeight {
			if termErr != nil {
				fmt.Fprintln(os.Stderr, "Environment variable TERM not set.")
				os.Exit(1)
			}
			outH = termH
			outW = int(math.Round(float64(outH) * float64(srcW) / float64(srcH) * 2.0))
			if outW < 1 {
				outW = 1
			}
		} else if cfg.termZoom {
			if termErr != nil {
				fmt.Fprintln(os.Stderr, "Environment variable TERM not set.")
				os.Exit(1)
			}
			outW = termW
			outH = termH
		} else if cfg.termFit {
			if termErr != nil {
				fmt.Fprintln(os.Stderr, "Environment variable TERM not set.")
				os.Exit(1)
			}
			hFromW := int(math.Round(float64(termW) * float64(srcH) / float64(srcW) * 0.5))
			wFromH := int(math.Round(float64(termH) * float64(srcW) / float64(srcH) * 2.0))
			fitsW := hFromW <= termH && hFromW > 0
			fitsH := wFromH <= termW && wFromH > 0
			if fitsW && fitsH {
				if termW*hFromW > wFromH*termH {
					outW = termW
					outH = hFromW
				} else {
					outW = wFromH
					outH = termH
				}
			} else if fitsW {
				outW = termW
				outH = hFromW
			} else if fitsH {
				outW = wFromH
				outH = termH
			} else {
				outW = wFromH
				outH = termH
				if outW > termW {
					outW = termW
					outH = hFromW
				}
			}
		}

		if cfg.verbose {
			comp := 1
			if _, ok := img.(*image.Gray); ok {
				comp = 1
			} else {
				if _, ok := img.(*image.YCbCr); ok {
					isGray := true
					for yy := 0; yy < 5 && yy < srcH; yy++ {
						for xx := 0; xx < 5 && xx < srcW; xx++ {
							r, g, b, _ := img.At(xx, yy).RGBA()
							if r != g || g != b {
								isGray = false
								break
							}
						}
						if !isGray {
							break
						}
					}
					if isGray {
						comp = 1
					} else {
						comp = 3
					}
				} else {
					comp = 3
				}
			}
			fmt.Fprintf(os.Stderr, "File: %s\n", fname)
			fmt.Fprintf(os.Stderr, "Source width: %d\n", srcW)
			fmt.Fprintf(os.Stderr, "Source height: %d\n", srcH)
			fmt.Fprintf(os.Stderr, "Source color components: %d\n", comp)
			fmt.Fprintf(os.Stderr, "Output width: %d\n", outW)
			fmt.Fprintf(os.Stderr, "Output height: %d\n", outH)
			fmt.Fprintf(os.Stderr, "Output palette (%d chars): '%s'\n", len([]rune(cfg.chars)), cfg.chars)
		}

		if cfg.clear {
			fmt.Fprint(outWriter, "\x1b[2J\x1b[0;0H")
		}

		sampled := sampleImage(img, outW, outH, cfg.flipx, cfg.flipy)

		runes := []rune(cfg.chars)
		n := len(runes)
		ascii := make([][]rune, outH)
		cols := make([][]color.RGBA, outH)
		for y := 0; y < outH; y++ {
			ascii[y] = make([]rune, outW)
			cols[y] = make([]color.RGBA, outW)
			for x := 0; x < outW; x++ {
				c := sampled[y][x]
				r, g, b := float64(c.R), float64(c.G), float64(c.B)
				lum := r*cfg.red + g*cfg.green + b*cfg.blue
				if lum < 0 {
					lum = 0
				}
				if lum > 255 {
					lum = 255
				}
				if cfg.invert {
					lum = 255 - lum
				}
				idxF := lum / 255.0 * float64(n-1)
				idx := int(math.Floor(idxF + 0.5))
				if idx < 0 {
					idx = 0
				}
				if idx >= n {
					idx = n - 1
				}
				ascii[y][x] = runes[idx]
				cols[y][x] = c
			}
		}

		if cfg.html {
			bg := "black"
			fg := "white"
			if cfg.invert {
				bg = "white"
				fg = "black"
			}
			if !cfg.htmlRaw {
				fmt.Fprintf(outWriter, "<?xml version='1.0' encoding='ISO-8859-1'?>\n")
				fmt.Fprintf(outWriter, "<!DOCTYPE html PUBLIC '-//W3C//DTD XHTML 1.0 Strict//EN'  'http://www.w3.org/TR/xhtml1/DTD/xhtml1-strict.dtd'>\n")
				fmt.Fprintf(outWriter, "<html xmlns='http://www.w3.org/1999/xhtml' lang='en' xml:lang='en'>\n")
				fmt.Fprintf(outWriter, "<head>\n")
				fmt.Fprintf(outWriter, "<title>%s</title>\n", htmlEscape(cfg.htmlTitle))
				fmt.Fprintf(outWriter, "<style type='text/css'>\n")
				fmt.Fprintf(outWriter, "body {\n")
				fmt.Fprintf(outWriter, "background-color: %s;\n", bg)
				fmt.Fprintf(outWriter, "}\n")
				fmt.Fprintf(outWriter, ".ascii {\n")
				fmt.Fprintf(outWriter, "   font-family: Courier;\n")
				if !cfg.colors {
					fmt.Fprintf(outWriter, "   color: %s;\n", fg)
				}
				fmt.Fprintf(outWriter, "   font-size:%dpt;\n", cfg.htmlFontSize)
				if !cfg.htmlNoBold {
					fmt.Fprintf(outWriter, "   font-weight: bold;\n")
				}
				fmt.Fprintf(outWriter, "}\n")
				fmt.Fprintf(outWriter, "</style>\n")
				fmt.Fprintf(outWriter, "</head>\n")
				fmt.Fprintf(outWriter, "<body>\n")
				fmt.Fprintf(outWriter, "<div class='ascii'><pre>\n")
			}
			useBR := cfg.colors
			if cfg.border {
				line := "+" + strings.Repeat("-", outW) + "+"
				if useBR {
					line += "<br/>"
				}
				fmt.Fprintln(outWriter, line)
			}
			for y := 0; y < outH; y++ {
				var sb strings.Builder
				if cfg.border {
					sb.WriteString("|")
				}
				for x := 0; x < outW; x++ {
					ch := ascii[y][x]
					c := cols[y][x]
					esc := htmlCharEscape(ch)
					if cfg.colors {
						r, g, b := int(c.R), int(c.G), int(c.B)
						if cfg.grayscale {
							lum := float64(r)*cfg.red + float64(g)*cfg.green + float64(b)*cfg.blue
							if cfg.invert {
								lum = 255 - lum
							}
							v := int(lum)
							r, g, b = v, v, v
						}
						hex := fmt.Sprintf("#%02x%02x%02x", r, g, b)
						if cfg.fill {
							// For fill, we will use bg=hex and set fg to black/white for contrast (approx)
							// To better match original, we will set bg=hex and fg as contrasting, but also include both?
							// Original for fill had color and background different, but we will use fg black/white
							lum := 0.299*float64(r) + 0.587*float64(g) + 0.114*float64(b)
							fgCol := "#000000"
							if lum < 128 {
								fgCol = "#ffffff"
							}
							sb.WriteString(fmt.Sprintf("<span style='color:%s; background-color:%s;'>%s</span>", fgCol, hex, esc))
						} else {
							sb.WriteString(fmt.Sprintf("<span style='color:%s;'>%s</span>", hex, esc))
						}
					} else {
						sb.WriteString(esc)
					}
				}
				if cfg.border {
					sb.WriteString("|")
				}
				if useBR {
					sb.WriteString("<br/>")
				}
				fmt.Fprintln(outWriter, sb.String())
			}
			if cfg.border {
				line := "+" + strings.Repeat("-", outW) + "+"
				if useBR {
					line += "<br/>"
				}
				fmt.Fprintln(outWriter, line)
			}
			if !cfg.htmlRaw {
				fmt.Fprintln(outWriter, "</pre>\n</div>\n</body>\n</html>")
			}
		} else {
			if cfg.border {
				fmt.Fprintf(outWriter, "+%s+\n", strings.Repeat("-", outW))
			}
			for y := 0; y < outH; y++ {
				if cfg.border {
					fmt.Fprint(outWriter, "|")
				}
				for x := 0; x < outW; x++ {
					ch := ascii[y][x]
					if cfg.colors {
						c := cols[y][x]
						if cfg.grayscale {
							lum := float64(c.R)*cfg.red + float64(c.G)*cfg.green + float64(c.B)*cfg.blue
							if cfg.invert {
								lum = 255 - lum
							}
							v := int(lum)
							c.R, c.G, c.B = uint8(v), uint8(v), uint8(v)
						}
						// Map to 8 colors + bold to approximate original
						r, g, b := c.R, c.G, c.B
						ri, gi, bi := 0, 0, 0
						if r >= 64 {
							ri = 1
						}
						if g >= 64 {
							gi = 1
						}
						if b >= 64 {
							bi = 1
						}
						// If all low, black
						if ri == 0 && gi == 0 && bi == 0 {
							// Check if not black but dark gray? Use 30
							fmt.Fprintf(outWriter, "\x1b[30m%s\x1b[0m", string(ch))
						} else {
							// Determine if bright: if any component >=192
							bright := ""
							if r >= 192 || g >= 192 || b >= 192 {
								bright = "\x1b[1m"
							}
							colorCode := 30 + ri + gi*2 + bi*4
							if colorCode == 37 && bright != "" {
								// Bold white is bright white, original used "\x1b[1mM\x1b[0m" for white
								fmt.Fprintf(outWriter, "%s%s\x1b[0m", bright, string(ch))
							} else if bright != "" {
								fmt.Fprintf(outWriter, "%s\x1b[%dm%s\x1b[0m", bright, colorCode, string(ch))
							} else {
								fmt.Fprintf(outWriter, "\x1b[%dm%s\x1b[0m", colorCode, string(ch))
							}
						}
					} else {
						fmt.Fprint(outWriter, string(ch))
					}
				}
				if cfg.border {
					fmt.Fprint(outWriter, "|")
				}
				fmt.Fprintln(outWriter)
			}
			if cfg.border {
				fmt.Fprintf(outWriter, "+%s+\n", strings.Repeat("-", outW))
			}
		}
		_ = idx
	}
	_ = outFile
}

func getTerminalSize() (int, int, error) {
	colsStr := os.Getenv("COLUMNS")
	linesStr := os.Getenv("LINES")
	term := os.Getenv("TERM")
	if term == "" {
		return 0, 0, fmt.Errorf("TERM not set")
	}
	if colsStr == "" || linesStr == "" {
		return 0, 0, fmt.Errorf("no size")
	}
	c, err1 := strconv.Atoi(colsStr)
	l, err2 := strconv.Atoi(linesStr)
	if err1 != nil || err2 != nil {
		return 0, 0, fmt.Errorf("bad size")
	}
	return c, l - 1, nil
}

func sampleImage(img image.Image, outW, outH int, flipx, flipy bool) [][]color.RGBA {
	bounds := img.Bounds()
	srcW := bounds.Dx()
	srcH := bounds.Dy()
	res := make([][]color.RGBA, outH)
	for y := 0; y < outH; y++ {
		var srcY int
		if outH == 1 {
			srcY = 0
		} else {
			srcY = (y*(srcH-1) + (outH-1)/2) / (outH - 1)
		}
		if flipy {
			srcY = srcH - 1 - srcY
		}
		row := make([]color.RGBA, outW)
		for x := 0; x < outW; x++ {
			var srcX int
			if outW == 1 {
				srcX = 0
			} else {
				srcX = (x*(srcW-1) + (outW-1)/2) / (outW - 1)
			}
			if flipx {
				srcX = srcW - 1 - srcX
			}
			c := img.At(bounds.Min.X+srcX, bounds.Min.Y+srcY)
			r, g, b, a := c.RGBA()
			row[x] = color.RGBA{uint8(r >> 8), uint8(g >> 8), uint8(b >> 8), uint8(a >> 8)}
		}
		res[y] = row
	}
	return res
}

func htmlEscape(s string) string {
	r := strings.NewReplacer("&", "&amp;", "<", "&lt;", ">", "&gt;", "\"", "&quot;", "'", "&#39;")
	return r.Replace(s)
}

func htmlCharEscape(ch rune) string {
	switch ch {
	case '&':
		return "&amp;"
	case '<':
		return "&lt;"
	case '>':
		return "&gt;"
	case '"':
		return "&quot;"
	case ' ':
		return "&nbsp;"
	default:
		if ch < 32 || ch > 126 {
			return fmt.Sprintf("&#%d;", ch)
		}
		return string(ch)
	}
}
